#include <stdio.h>

/* teste do desafio a-troca-que-nao-troca — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: sem captura de stdout. Os dois lados da mesma historia, no
   mesmo desafio: DENTRO da caixa a troca vale (92), FORA dela nada mudou
   (29). Cada cenario usa um par novo para que valor fixo devolvido nao passe. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
int tentarTrocar(int a, int b);
int aTrocaQueNaoTroca(int x, int y);

SM_TEST(dentro_da_caixa_a_troca_acontece) {
    checa_int("dentro da caixa, 2 e 9 viram 9 e 2", tentarTrocar(2, 9), 92,
              "nas copias a troca vale: a ficou 9 e b ficou 2");
}

SM_TEST(fora_da_caixa_nada_mudou) {
    checa_int("fora da caixa, x e y seguem 2 e 9", aTrocaQueNaoTroca(2, 9), 29,
              "a chamada mexeu nas copias; x e y de quem chamou nao mudaram");
}

SM_TEST(outro_par_a_mesma_historia) {
    checa_int("dentro da caixa, 4 e 7 viram 7 e 4", tentarTrocar(4, 7), 74,
              "a troca das copias acontece com qualquer par");
    checa_int("fora da caixa, x e y seguem 4 e 7", aTrocaQueNaoTroca(4, 7), 47,
              "de fora, a ordem continua a mesma depois da chamada");
}

solutionCode:
int tentarTrocar(int a, int b) {
    int guardado = a;
    a = b;
    b = guardado;
    return a * 10 + b;
}

int aTrocaQueNaoTroca(int x, int y) {
    tentarTrocar(x, y);
    return x * 10 + y;
}
